package com.aicrm.web.platform;
import com.aicrm.kernel.security.*;import com.aicrm.platform.application.SalesDocumentService;import com.aicrm.web.api.ApiResponse;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/v1/sales-documents") public class SalesDocumentV1Controller { private final SalesDocumentService service;public SalesDocumentV1Controller(SalesDocumentService service){this.service=service;}record CreateRequest(@NotBlank String title,@NotBlank String category,@NotBlank String content){}record VersionRequest(@NotNull Long version){}record View(String id,String title,String category,String content,String status,String ownerUserId,Instant publishedAt,Instant archivedAt,long version){}@PostMapping public ResponseEntity<ApiResponse<View>>create(@RequestBody CreateRequest r,@RequestHeader("Idempotency-Key")String k){return ResponseEntity.status(HttpStatus.CREATED).body(ok(view(service.create(ActorContext.require(),new SalesDocumentService.Create(r.title(),r.category(),r.content()),k))));}@GetMapping public ApiResponse<List<View>>list(){return ok(service.list(ActorContext.require()).stream().map(this::view).toList());}@GetMapping("/{id}")public ApiResponse<View>get(@PathVariable long id){return ok(view(service.get(ActorContext.require(),id)));}@PostMapping("/{id}/actions/publish")public ApiResponse<View>publish(@PathVariable long id,@RequestBody VersionRequest r){return ok(view(service.publish(ActorContext.require(),id,new SalesDocumentService.Versioned(r.version()))));}@PostMapping("/{id}/actions/archive")public ApiResponse<View>archive(@PathVariable long id,@RequestBody VersionRequest r){return ok(view(service.archive(ActorContext.require(),id,new SalesDocumentService.Versioned(r.version()))));}private View view(SalesDocumentService.Document d){return new View(String.valueOf(d.id()),d.title(),d.category(),d.content(),d.status().name(),String.valueOf(d.ownerUserId()),d.publishedAt(),d.archivedAt(),d.version());}private<T>ApiResponse<T>ok(T x){return ApiResponse.success(x,TraceContext.get());}}
